  entities: Record<string, string>;
};

export interface WorldProtocol {
  reset(): WorldStateHandle;
  applyOperation(
    state: WorldStateHandle,
    operationDisplayName: string
  ): { success: true; newState: WorldStateHandle } | { success: false; error: string };
  getEntityState(state: WorldStateHandle, entityDisplayName: string): string;
  toAbstractSnapshot(state: WorldStateHandle): Record<string, string>;
}

const initialState: WorldStateHandle = {
  entities: {
    Zef: "nim",
  },
};

const copyState = (state: WorldStateHandle): WorldStateHandle => ({
  entities: { ...state.entities },
});

export const protocol: WorldProtocol = {
  reset(): WorldStateHandle {
    return copyState(initialState);
  },

  applyOperation(
    state: WorldStateHandle,
    operationDisplayName: string
  ):
    | { success: true; newState: WorldStateHandle }
    | { success: false; error: string } {
    const currentState = state.entities.Zef;

    if (operationDisplayName === "advanceZef") {
      if (currentState !== "nim") {
        return {
          success: false,
          error: `Cannot apply advanceZef when Zef is ${currentState}`,
        };
      }

      const newState = copyState(state);
      newState.entities.Zef = "pex";
      return { success: true, newState };
    }

    if (operationDisplayName === "resetZef") {
      if (currentState !== "pex") {
        return {
          success: false,
          error: `Cannot apply resetZef when Zef is ${currentState}`,
        };
      }

      const newState = copyState(state);
      newState.entities.Zef = "nim";
      return { success: true, newState };
    }

    return {
      success: false,
      error: `Unknown operation: ${operationDisplayName}`,
    };
  },

  getEntityState(state: WorldStateHandle, entityDisplayName: string): string {
    return state.entities[entityDisplayName] ?? "unknown";
  },

  toAbstractSnapshot(state: WorldStateHandle): Record<string, string> {
    return { ...state.entities };
  },
};
"}],"workingNote":"Added resetZef with a guarded pex→nim transition, immutable state copies, and snapshot/query support. The existing nim→pex advanceZef transition remains available; invalid source states and unknown operations return failures."}

